//! Direct messages: 1:1s, groups, pinning and hiding.
//! The contract (`DmStore`) and its SQLite implementation live together.

use protocol::Id;

use super::queries;
use super::sqlite::SqliteStorage;
use crate::models::*;
use crate::time::now_ms;

#[async_trait::async_trait]
pub trait DmStore: Send + Sync {
    async fn list_dm_participant_users(&self, channel_id: Id) -> anyhow::Result<Vec<User>>;

    /// Returns the existing 1:1 DM channel between `user_a` and
    /// `user_b`, or creates one (`new_channel_id`, pre-generated by the
    /// caller) if none exists.
    async fn get_or_create_dm(
        &self,
        new_channel_id: Id,
        user_a: Id,
        user_b: Id,
    ) -> anyhow::Result<Channel>;

    /// Creates a brand-new group DM channel (`new_channel_id`,
    /// pre-generated by the caller) with `creator` plus every id in
    /// `other_ids`. Unlike `get_or_create_dm`, there's no dedup — like
    /// Discord, starting a new group makes a new channel every time,
    /// even with the exact same people.
    async fn create_group_dm(
        &self,
        new_channel_id: Id,
        creator: Id,
        other_ids: Vec<Id>,
    ) -> anyhow::Result<Channel>;

    async fn list_dms_for_user(&self, user_id: Id) -> anyhow::Result<Vec<DmChannelSummary>>;

    async fn is_dm_participant(&self, channel_id: Id, user_id: Id) -> anyhow::Result<bool>;

    async fn dm_participant_count(&self, channel_id: Id) -> anyhow::Result<i64>;

    /// Whether `channel_id` is somebody's private "note to self" chat
    /// (`channels.is_self_dm`) — see `api::dms::add_participant` and
    /// `api::invites::create` for why nothing may ever be added to one.
    async fn is_self_dm(&self, channel_id: Id) -> anyhow::Result<bool>;

    /// Adds `new_user_id` to an existing DM channel — the "add people"
    /// step that grows a 1:1 into a group. The caller is responsible
    /// for checking participation/size-cap first (see `api::dms`).
    async fn add_dm_participant(&self, channel_id: Id, new_user_id: Id) -> anyhow::Result<()>;

    /// Removes `user_id` from a group DM — "leave conversation". The
    /// caller checks it's actually a group first (see `api::dms::leave`
    /// — a 1:1 or the self-DM can't be left this way, only hidden).
    async fn remove_dm_participant(&self, channel_id: Id, user_id: Id) -> anyhow::Result<()>;

    async fn set_dm_pinned(&self, user_id: Id, channel_id: Id, pinned: bool) -> anyhow::Result<()>;

    /// Hides a DM from `user_id`'s own list until new activity —
    /// see `queries::dms::list_for_user`'s doc comment for exactly
    /// when it reappears.
    async fn hide_dm(&self, user_id: Id, channel_id: Id) -> anyhow::Result<()>;

    /// The counterpart to `hide_dm`: makes a hidden conversation show up
    /// in `user_id`'s list again right now, without waiting for a new
    /// message — used when they deliberately open it (a friend they'd
    /// closed the chat with).
    async fn unhide_dm(&self, user_id: Id, channel_id: Id) -> anyhow::Result<()>;
}

#[async_trait::async_trait]
impl DmStore for SqliteStorage {
    async fn list_dm_participant_users(&self, channel_id: Id) -> anyhow::Result<Vec<User>> {
        self.with_conn(move |conn| queries::users::list_for_dm_channel(conn, channel_id)).await
    }

    async fn get_or_create_dm(
        &self,
        new_channel_id: Id,
        user_a: Id,
        user_b: Id,
    ) -> anyhow::Result<Channel> {
        self.with_conn(move |conn| {
            let tx = conn.unchecked_transaction()?;
            if user_a == user_b {
                if let Some(existing) = queries::dms::find_existing_self(&tx, user_a)? {
                    return Ok(existing);
                }
                queries::dms::create_self(&tx, new_channel_id, user_a)?;
            } else {
                if let Some(existing) = queries::dms::find_existing(&tx, user_a, user_b)? {
                    return Ok(existing);
                }
                queries::dms::create(&tx, new_channel_id, user_a, user_b)?;
            }
            let channel = queries::channels::by_id(&tx, new_channel_id)?
                .ok_or(rusqlite::Error::QueryReturnedNoRows)?;
            tx.commit()?;
            Ok(channel)
        })
        .await
    }

    async fn create_group_dm(
        &self,
        new_channel_id: Id,
        creator: Id,
        other_ids: Vec<Id>,
    ) -> anyhow::Result<Channel> {
        self.with_conn(move |conn| {
            let tx = conn.unchecked_transaction()?;
            queries::dms::create_group(&tx, new_channel_id, creator, &other_ids)?;
            let channel = queries::channels::by_id(&tx, new_channel_id)?
                .ok_or(rusqlite::Error::QueryReturnedNoRows)?;
            tx.commit()?;
            Ok(channel)
        })
        .await
    }

    async fn list_dms_for_user(&self, user_id: Id) -> anyhow::Result<Vec<DmChannelSummary>> {
        self.with_conn(move |conn| {
            let rows = queries::dms::list_for_user(conn, user_id)?;
            let mut result = Vec::with_capacity(rows.len());
            for (channel, other_ids, pinned, is_self_dm) in rows {
                let mut participants = Vec::with_capacity(other_ids.len());
                for id in other_ids {
                    let u = queries::users::by_id(conn, id)?
                        .ok_or(rusqlite::Error::QueryReturnedNoRows)?;
                    participants.push(u);
                }
                // A real self-DM has no other participant row by
                // design — show the viewer themselves. A real 1:1 DM
                // can *also* end up with no other participant row once
                // the other side's account is hard-deleted, but that's
                // not a self-DM: `participants` stays empty (the
                // frontend renders that case as a departed
                // conversation, not as "yourself" — see UX_FEEDBACK.md).
                if is_self_dm && participants.is_empty() {
                    let me = queries::users::by_id(conn, user_id)?
                        .ok_or(rusqlite::Error::QueryReturnedNoRows)?;
                    participants.push(me);
                }
                result.push(DmChannelSummary { channel, participants, pinned });
            }
            Ok(result)
        })
        .await
    }

    async fn is_dm_participant(&self, channel_id: Id, user_id: Id) -> anyhow::Result<bool> {
        self.with_conn(move |conn| queries::dms::is_participant(conn, channel_id, user_id)).await
    }

    async fn dm_participant_count(&self, channel_id: Id) -> anyhow::Result<i64> {
        self.with_conn(move |conn| queries::dms::participant_count(conn, channel_id)).await
    }

    async fn is_self_dm(&self, channel_id: Id) -> anyhow::Result<bool> {
        self.with_conn(move |conn| queries::dms::is_self_dm(conn, channel_id)).await
    }

    async fn add_dm_participant(&self, channel_id: Id, new_user_id: Id) -> anyhow::Result<()> {
        self.with_conn(move |conn| queries::dms::add_participant(conn, channel_id, new_user_id))
            .await
    }

    async fn remove_dm_participant(&self, channel_id: Id, user_id: Id) -> anyhow::Result<()> {
        self.with_conn(move |conn| queries::dms::remove_participant(conn, channel_id, user_id))
            .await
    }

    async fn set_dm_pinned(&self, user_id: Id, channel_id: Id, pinned: bool) -> anyhow::Result<()> {
        self.with_conn(move |conn| {
            if pinned {
                queries::pinned_dms::pin(conn, user_id, channel_id, now_ms())
            } else {
                queries::pinned_dms::unpin(conn, user_id, channel_id)
            }
        })
        .await
    }

    async fn hide_dm(&self, user_id: Id, channel_id: Id) -> anyhow::Result<()> {
        self.with_conn(move |conn| queries::hidden_dms::hide(conn, user_id, channel_id, now_ms()))
            .await
    }

    async fn unhide_dm(&self, user_id: Id, channel_id: Id) -> anyhow::Result<()> {
        self.with_conn(move |conn| queries::hidden_dms::unhide(conn, user_id, channel_id)).await
    }
}
